import { Logo } from "@/components/logo/logo";
import { MarketingCtaButton } from "@/components/ui/marketing-cta-button";
import { MobileNavDrawer } from "@/components/nav/mobile-nav-drawer";
import {
  MARKETING_GUTTER_WIDTH,
  marketingContentPaddingX,
  marketingLayoutBorderColor,
} from "@/components/layout/marketing-frame";
import { MarketingPageWidth } from "@/components/layout/marketing-page-width";
import {
  TOP_NAV_HEIGHT,
  topNavCtaStyles,
  topNavRowProps,
} from "@/components/nav/nav-styles";
import { ResourcesNavMenu } from "@/components/nav/resources-nav-menu";
import { SolutionsNavMenu } from "@/components/nav/solutions-nav-menu";
import { COMPANY_LINKS } from "@/features/company/company-links";
import {
  SOLUTIONS_PATH,
  SOLUTION_CAPABILITIES,
} from "@/features/solutions/solutions";
import { Box, Button, Flex, IconButton } from "@chakra-ui/react";
import { Menu } from "lucide-react";
import React, { useEffect, useState } from "react";
import { useLocation, useNavigate } from "react-router";

export { TOP_NAV_HEIGHT };

export const AppTopNav: React.FC = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const [drawerOpen, setDrawerOpen] = useState(false);

  // Close drawer on route change
  useEffect(() => {
    setDrawerOpen(false);
  }, [location.pathname]);

  // The header overlays the hero, whose drifting grid and mesh wash run up
  // behind it, so at the top of the page it carries no background of its own.
  // Once the hero scrolls away there is nothing behind the links but body
  // copy, so the backdrop comes back to keep them legible.
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    // Roughly the nav's own height: enough that the swap lands after the
    // header has cleared its starting position, not on the first pixel.
    const onScroll = () => setScrolled(window.scrollY > TOP_NAV_HEIGHT);
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, [location.pathname]);

  // Every marketing hero is light under the refresh, so the nav no longer
  // swaps treatments per route.
  const navColor = "indigo.900";
  const navHoverColor = "indigo.700";

  const navItems = [
    {
      label: "Solutions",
      children: SOLUTION_CAPABILITIES.map((c) => ({
        label: c.title,
        path: `${SOLUTIONS_PATH}/${c.slug}`,
      })),
    },
    {
      label: "Resources",
      children: COMPANY_LINKS.map((link) => ({
        label: link.title,
        path: link.path,
      })),
    },
  ];

  return (
    <>
      <Box
        as="header"
        position="fixed"
        top={0}
        left={0}
        right={0}
        zIndex={100}
        borderBottom="1px solid"
        borderColor={scrolled ? marketingLayoutBorderColor : "transparent"}
        bg={scrolled ? "slate.10/90" : "transparent"}
        style={{ transition: "background 200ms ease, border-color 200ms ease" }}
      >
        <MarketingPageWidth>
          <Flex w="full" align="stretch" {...topNavRowProps}>
            <Box
              display={{ base: "none", md: "block" }}
              w={MARKETING_GUTTER_WIDTH}
              flexShrink={0}
            />
            <Box
              flex="1"
              minW={0}
              px={marketingContentPaddingX}
              display="grid"
              gridTemplateColumns={{ base: "1fr auto", md: "1fr auto 1fr" }}
              alignItems="center"
            >
              <Flex justify="flex-start" minW={0}>
                <Logo color="indigo.900" homeLink />
              </Flex>

              <Flex
                as="nav"
                gap="6px"
                display={{ base: "none", md: "flex" }}
                align="center"
                justify="center"
              >
                <SolutionsNavMenu
                  navColor={navColor}
                  navHoverColor={navHoverColor}
                />
                <ResourcesNavMenu
                  navColor={navColor}
                  navHoverColor={navHoverColor}
                />
              </Flex>

              <Flex justify="flex-end" minW={0}>
                <Flex
                  gap="6px"
                  alignItems="center"
                  display={{ base: "none", md: "flex" }}
                >
                  <Button
                    variant="ghost"
                    color={navColor}
                    onClick={() =>
                      window.open("https://app.rengoai.com/", "_blank")
                    }
                    {...topNavCtaStyles}
                    h="34px"
                    minH="34px"
                    _hover={{
                      bg: "transparent",
                      color: navHoverColor,
                    }}
                  >
                    Log in
                  </Button>
                  <MarketingCtaButton
                    size="sm"
                    showArrow={false}
                    onClick={() =>
                      window.open("mailto:sales@rengoai.com", "_blank")
                    }
                  >
                    Get Started
                  </MarketingCtaButton>
                </Flex>

                <IconButton
                  display={{ base: "flex", md: "none" }}
                  aria-label="Open menu"
                  variant="ghost"
                  size="sm"
                  color="indigo.900"
                  _hover={{ bg: "transparent" }}
                  onClick={() => setDrawerOpen(true)}
                >
                  <Menu size={22} />
                </IconButton>
              </Flex>
            </Box>
            <Box
              display={{ base: "none", md: "block" }}
              w={MARKETING_GUTTER_WIDTH}
              flexShrink={0}
            />
          </Flex>
        </MarketingPageWidth>
      </Box>

      <MobileNavDrawer
        open={drawerOpen}
        onOpenChange={setDrawerOpen}
        navItems={navItems}
        onNavigate={(path) => navigate(path)}
      />
    </>
  );
};
